"""Validate and normalize distribution and namespace names."""

import re

__all__ = ["normalize_name", "is_valid_namespace", "hyphen_depth"]

_NAME = re.compile(r"[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?")
_SEPARATORS = re.compile(r"[-_.]+")


def normalize_name(name):
    """Return a valid project name in its normalized form.

    Raise TypeError for non-strings and ValueError for invalid names.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if _NAME.fullmatch(name) is None:
        raise ValueError(f"invalid package name: {name!r}")
    return _SEPARATORS.sub("-", name).lower()


def is_valid_namespace(name):
    """Return whether name is a valid distribution namespace."""
    try:
        normalize_name(name)
    except (TypeError, ValueError):
        return False
    return True


def hyphen_depth(name):
    """Return the number of hyphens in the normalized name."""
    return normalize_name(name).count("-")
"""Manage repository-local namespace grants."""

from dataclasses import dataclass

from .matching import namespace_matches
from .normalize import hyphen_depth, normalize_name

__all__ = [
    "Grant", "GrantStore", "GrantError", "InvalidNamespaceError",
    "OverlapError", "DepthLimitError", "UnknownGrantError", "grants_overlap",
    "DEFAULT_DEPTH_LIMIT",
]

DEFAULT_DEPTH_LIMIT = 3


class GrantError(ValueError):
    """Base class for invalid grant operations."""


class InvalidNamespaceError(GrantError):
    """A grant's namespace is not a valid package name."""


class OverlapError(GrantError):
    """A namespace overlaps a grant held by another owner."""


class DepthLimitError(GrantError):
    """A namespace exceeds the store's hyphen depth limit."""


class UnknownGrantError(GrantError):
    """An operation requires a grant that does not exist."""


def _validate_owner(owner):
    if not isinstance(owner, str) or not owner:
        raise ValueError("owner must be a non-empty string")
    return owner


def _normalize_namespace(namespace):
    try:
        return normalize_name(namespace)
    except (TypeError, ValueError) as exc:
        raise InvalidNamespaceError(str(exc)) from exc


def grants_overlap(first, second):
    """Return whether either namespace contains or equals the other."""
    first = normalize_name(first) + "-"
    second = normalize_name(second) + "-"
    return first.startswith(second) or second.startswith(first)


@dataclass(frozen=True)
class Grant:
    """An immutable grant of a normalized namespace to an owner."""

    name: str
    owner: str

    def __post_init__(self):
        object.__setattr__(self, "name", _normalize_namespace(self.name))
        _validate_owner(self.owner)


class GrantStore:
    """An in-memory grant collection with an optional hyphen depth limit."""

    def __init__(self, depth_limit=DEFAULT_DEPTH_LIMIT):
        if depth_limit is not None:
            if (not isinstance(depth_limit, int)
                    or isinstance(depth_limit, bool)):
                raise TypeError("depth_limit must be an integer or None")
            if depth_limit < 0:
                raise ValueError("depth_limit must not be negative")
        self._depth_limit = depth_limit
        self._grants = {}

    @property
    def depth_limit(self):
        """Maximum allowed hyphen depth, or None for no limit."""
        return self._depth_limit

    def __len__(self):
        return len(self._grants)

    def __contains__(self, namespace):
        return _normalize_namespace(namespace) in self._grants

    def _check_overlap(self, namespace, owner, *, exclude=None):
        for name, grant in self._grants.items():
            if name != exclude and grant.owner != owner:
                if grants_overlap(namespace, name):
                    raise OverlapError(
                        f"namespace {namespace!r} overlaps the grant "
                        f"{name!r} owned by {grant.owner!r}"
                    )

    def reserve(self, namespace, owner):
        """Reserve namespace for owner and return its Grant.

        Reserving the same namespace for the same owner is idempotent.
        """
        grant = Grant(namespace, owner)
        if (self.depth_limit is not None
                and hyphen_depth(grant.name) > self.depth_limit):
            raise DepthLimitError(
                f"namespace {grant.name!r} exceeds depth limit "
                f"{self.depth_limit}"
            )
        self._check_overlap(grant.name, owner)
        self._grants[grant.name] = grant
        return grant

    def transfer(self, namespace, owner):
        """Transfer a grant, unless that would conflict with another grant."""
        grant = Grant(namespace, owner)
        self._require(grant.name)
        self._check_overlap(grant.name, owner, exclude=grant.name)
        self._grants[grant.name] = grant
        return grant

    def remove(self, namespace):
        """Remove and return a grant, raising UnknownGrantError if absent."""
        namespace = _normalize_namespace(namespace)
        grant = self._require(namespace)
        del self._grants[namespace]
        return grant

    def get(self, namespace):
        """Return the exact grant, or None when it does not exist."""
        return self._grants.get(_normalize_namespace(namespace))

    def _require(self, namespace):
        grant = self.get(namespace)
        if grant is None:
            raise UnknownGrantError(f"unknown grant: {namespace!r}")
        return grant

    def namespaces(self):
        """Return all granted namespace names in sorted order."""
        return sorted(self._grants)

    def matching(self, project):
        """Return all grants matching project, sorted by namespace name."""
        project = normalize_name(project)
        return [self._grants[name] for name in self.namespaces()
                if namespace_matches(name, project)]

    def parent(self, namespace):
        """Return the granted immediate parent's name, or None."""
        namespace = _normalize_namespace(namespace)
        if namespace not in self._grants:
            return None
        parent, separator, _ = namespace.rpartition("-")
        if separator and parent in self._grants:
            return parent
        return None

    def children(self, namespace):
        """Return sorted names of granted immediate children."""
        namespace = _normalize_namespace(namespace)
        if namespace not in self._grants:
            return []
        return [name for name in self.namespaces()
                if name.rpartition("-")[0] == namespace]
"""Authorize uploads against repository grants and grandfathered projects."""

from .grants import _validate_owner
from .normalize import normalize_name

__all__ = [
    "authorize_upload", "GrandfatheredRegistry", "UploadConflictError",
    "CONFLICT_STATUS",
]

CONFLICT_STATUS = 409


class UploadConflictError(ValueError):
    """An uploader does not own a namespace matched by their project."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = normalize_name(project)
        self.namespace = normalize_name(namespace)
        self.owner = _validate_owner(owner)
        super().__init__(
            f"409 Conflict: {self.project!r} matches reserved namespace "
            f"{self.namespace!r}; uploader {owner!r} has no grant"
        )


class GrandfatheredRegistry:
    """Normalized projects exempt from namespace upload restrictions."""

    def __init__(self, projects=()):
        self._projects = {normalize_name(project) for project in projects}

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return self.covers(project)

    def add(self, project):
        """Exempt project from namespace upload restrictions."""
        self._projects.add(normalize_name(project))

    def discard(self, project):
        """Remove an exemption if present."""
        self._projects.discard(normalize_name(project))

    def covers(self, project):
        """Return whether this exact normalized project is exempt."""
        return normalize_name(project) in self._projects

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None):
    """Allow an upload or raise UploadConflictError.

    Validate owner before consulting grants, including for unreserved projects.
    Exemptions apply to projects, not to an entire namespace.
    Return True on success.
    """
    _validate_owner(owner)
    project = normalize_name(project)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            raise UploadConflictError(project, grant.name, owner)
    return True
"""Repository-local state and JSON and HTML views for reserved namespaces."""

from html import escape

from .grants import GrantStore, UnknownGrantError, _validate_owner
from .normalize import normalize_name
from .uploads import GrandfatheredRegistry

__all__ = [
    "RepositoryIndex", "NotSupportedError", "API_VERSION",
    "LEGACY_API_VERSION",
]

API_VERSION = "1.5"
LEGACY_API_VERSION = "1.4"


class NotSupportedError(ValueError):
    """A repository does not support namespace metadata."""


class RepositoryIndex:
    """Hold projects, grants, and exemptions for one package repository."""

    def __init__(self, store=None, *, supports_namespaces=True,
                 grandfathered=None):
        self.store = GrantStore() if store is None else store
        self.supports_namespaces = supports_namespaces
        self.grandfathered = (GrandfatheredRegistry() if grandfathered is None
                              else grandfathered)
        self._projects = {}

    @property
    def api_version(self):
        """The JSON API version advertised by this repository."""
        return API_VERSION if self.supports_namespaces else LEGACY_API_VERSION

    def register_project(self, project, owner):
        """Record ownership without performing upload authorization."""
        _validate_owner(owner)
        self._projects[normalize_name(project)] = owner

    def project_owner(self, project):
        """Return a project's owner, or None for an unknown project."""
        return self._projects.get(normalize_name(project))

    def projects(self):
        """Return registered project names in sorted order."""
        return sorted(self._projects)

    def project_detail(self, project):
        """Return project metadata with supported namespace associations."""
        project = normalize_name(project)
        detail = {"name": project}
        if self.supports_namespaces:
            owner = self.project_owner(project)
            matches = [{"name": grant.name, "owned": grant.owner == owner}
                       for grant in self.store.matching(project)]
            detail["namespaces"] = matches or None
        return detail

    def _require_support(self):
        if not self.supports_namespaces:
            raise NotSupportedError("repository does not support namespaces")

    def list_namespaces(self):
        """Return the /namespaces versioned envelope with name-only entries."""
        self._require_support()
        return {"api_version": self.api_version,
                "namespaces": [{"name": name}
                               for name in self.store.namespaces()]}

    def namespace_detail(self, namespace):
        """Return the /namespace/<namespace> mapping for an active grant."""
        self._require_support()
        namespace = normalize_name(namespace)
        grant = self.store.get(namespace)
        if grant is None:
            raise UnknownGrantError(f"unknown grant: {namespace!r}")
        return {"name": namespace, "parent": self.store.parent(namespace),
                "children": self.store.children(namespace),
                "owner": grant.owner}

    def simple_html(self, project, files=()):
        """Render HTML Simple API file links without namespace metadata.

        Each file is a mapping with 'filename' and 'url' string entries.
        """
        project = escape(normalize_name(project))
        lines = ["<!DOCTYPE html>", "<html>", "<head>",
                 f"<title>Links for {project}</title>", "</head>", "<body>",
                 f"<h1>Links for {project}</h1>"]
        for file in files:
            filename = escape(file["filename"])
            url = escape(file["url"], quote=True)
            lines.append(f'<a href="{url}">{filename}</a>')
        lines.extend(["</body>", "</html>"])
        return "\n".join(lines) + "\n"
"""Optional installer policies scoped to the repository being evaluated."""

from .grants import _validate_owner
from .matching import namespace_matches
from .normalize import normalize_name

__all__ = ["SecurityPolicy"]


class SecurityPolicy:
    """Allow an owner's projects under actively granted policy namespaces."""

    def __init__(self, namespaces, owner):
        self.namespaces = tuple(sorted({normalize_name(name)
                                        for name in namespaces}))
        self.owner = _validate_owner(owner)

    def allows(self, project, index):
        """Return whether project satisfies this policy on index."""
        project = normalize_name(project)
        if not index.supports_namespaces:
            return False
        if index.project_owner(project) != self.owner:
            return False
        for namespace in self.namespaces:
            if namespace_matches(namespace, project):
                grant = index.store.get(namespace)
                if grant is not None and grant.owner == self.owner:
                    return True
        return False

    def evaluate(self, projects, index):
        """Return a mapping from normalized project names to decisions."""
        return {normalize_name(project): self.allows(project, index)
                for project in projects}

